(()=>{'use strict';const $=s=>document.querySelector(s);let duration=300,remaining=300,deadline=0,ticker=null,state='ready',audioContext=null;const display=$('#time-display');const status=$('#timer-status');const progress=$('.progress-track');const fill=$('#progress-fill');function format(s){const n=Math.max(0,Math.ceil(s));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}function renderTimer(){display.textContent=format(remaining);display.setAttribute('aria-label',`남은 시간 ${Math.floor(Math.ceil(remaining)/60)}분 ${Math.ceil(remaining)%60}초`);status.textContent={ready:'준비',running:'진행 중',paused:'일시 정지',done:'종료'}[state];status.className='status-pill '+state;$('#start-pause').innerHTML=state==='running'?'일시 정지 <span aria-hidden="true">Ⅱ</span>':state==='paused'?'계속하기 <span aria-hidden="true">▶</span>':'시작하기 <span aria-hidden="true">▶</span>';const pct=duration?Math.max(0,Math.min(100,remaining/duration*100)):0;fill.style.width=`${pct}%`;progress.setAttribute('aria-valuenow',String(Math.round(pct)));$('#completion-message').hidden=state!=='done'}function clearTick(){if(ticker){clearInterval(ticker);ticker=null}}function beep(){try{if(!audioContext)return;const ctx=audioContext;for(let i=0;i<3;i++){const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type='sine';osc.frequency.value=880;gain.gain.setValueAtTime(.0001,ctx.currentTime+i*.3);gain.gain.exponentialRampToValueAtTime(.16,ctx.currentTime+i*.3+.02);gain.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+i*.3+.2);osc.connect(gain).connect(ctx.destination);osc.start(ctx.currentTime+i*.3);osc.stop(ctx.currentTime+i*.3+.22)}}catch{}}function tick(){remaining=Math.max(0,(deadline-Date.now())/1000);if(remaining<=0){remaining=0;state='done';clearTick();beep()}renderTimer()}function setDuration(seconds){clearTick();duration=seconds;remaining=seconds;state='ready';document.querySelectorAll('.preset').forEach(b=>b.classList.toggle('active',Number(b.dataset.seconds)===seconds));$('#minutes').value=Math.floor(seconds/60);$('#seconds').value=seconds%60;$('#time-error').textContent='';renderTimer()}document.querySelectorAll('.preset').forEach(b=>b.addEventListener('click',()=>setDuration(Number(b.dataset.seconds))));$('#custom-time').addEventListener('submit',e=>{e.preventDefault();const m=Number($('#minutes').value),s=Number($('#seconds').value);if(!Number.isInteger(m)||!Number.isInteger(s)||m<0||m>180||s<0||s>59||m*60+s<1||m*60+s>10800){$('#time-error').textContent='0분 1초부터 180분까지 설정해 주세요.';return}setDuration(m*60+s)});$('#start-pause').addEventListener('click',()=>{if(state==='running'){tick();clearTick();if(state==='running')state='paused';renderTimer();return}if(state==='done'){remaining=duration}if(remaining<=0)return;try{const Ctx=window.AudioContext||window.webkitAudioContext;if(Ctx){audioContext=audioContext||new Ctx();audioContext.resume()}}catch{}deadline=Date.now()+remaining*1000;state='running';clearTick();ticker=setInterval(tick,150);renderTimer()});$('#reset').addEventListener('click',()=>setDuration(duration));$('#add-minute').addEventListener('click',()=>{if(duration+60>10800){$('#time-error').textContent='최대 180분까지 늘릴 수 있어요.';return}duration+=60;remaining+=60;if(state==='running')deadline+=60000;if(state==='done')state='ready';document.querySelectorAll('.preset').forEach(b=>b.classList.remove('active'));$('#minutes').value=Math.floor(duration/60);$('#seconds').value=duration%60;$('#time-error').textContent='';renderTimer()});$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#timer-view').requestFullscreen()}catch{alert('이 브라우저에서는 전체 화면을 열 수 없어요.')}});document.addEventListener('visibilitychange',()=>{if(state==='running')tick()});renderTimer();})();

